const game = new GF.Game({id:'core-awakening',title:'Core Awakening',width:960,height:540,palette:['#00B2D2','#C0C0C0','#FFAA00','#FF5000'],background:'#0b0e1a'});
let player={x:480,y:270,width:40,height:40,health:3};
let enemies=[];
let score=0;
let enemySpawnTime=1.5;
let enemyTimer=0;
let enemySpeed=100;
let backgroundLayer1={y:0};
let backgroundLayer2={y:0};

function updateBackground(dt) {
    backgroundLayer1.y += 10 * dt;
    backgroundLayer2.y += 5 * dt;
    if (backgroundLayer1.y >= 540) backgroundLayer1.y = 0;
    if (backgroundLayer2.y >= 540) backgroundLayer2.y = 0;
}

game.add('play', {
    init() {
        score = 0;
        player.health = 3;
        enemies = [];
        enemyTimer = 0;
        enemySpawnTime = 1.5;
        backgroundLayer1.y = 0;
        backgroundLayer2.y = 0;
    },
    update(dt) {
        enemyTimer += dt;
        updateBackground(dt);
        while (enemyTimer > enemySpawnTime) {
            enemies.push({x:GF.math.rand(0, 960), y:0, width:40, height:40});
            enemyTimer -= enemySpawnTime;
            enemySpawnTime = Math.max(0.5, enemySpawnTime * 0.95);
            score += 1;
            game.addScore(1);
            GF.Sfx.beep({freq:440,dur:0.1});
        }
        for (let e of enemies) {
            e.y += enemySpeed * dt;
            if (e.y > 540) {
                enemies.splice(enemies.indexOf(e), 1);
            }
        }
        if (game.input.keys['ArrowLeft']) player.x -= 200 * dt;
        if (game.input.keys['ArrowRight']) player.x += 200 * dt;
        if (game.input.pressed('Space')) {
            for (let e of enemies) {
                if (e.x < player.x + player.width && e.x + e.width > player.x && e.y < player.y + player.height && e.y + e.height > player.y) {
                    game.hitStop(0.1);
                    game.shake(5, 0.2);
                    score += 5;
                    game.addScore(5);
                    enemies.splice(enemies.indexOf(e), 1);
                    game.burst(e.x + 20, e.y + 20, {count:10, speed:100, size:5, life:0.5, colors:['#FFAA00','#FF5000']});
                    GF.Sfx.noise({dur:0.2,vol:0.5});
                }
            }
        }
        if (player.health <= 0) game.gameOver({message:'GAME OVER'});
    },
    draw(ctx) {
        // Draw background
        ctx.fillStyle = '#C0C0C0';
        ctx.fillRect(0, backgroundLayer1.y, 960, 540);
        ctx.fillRect(0, backgroundLayer1.y - 540, 960, 540);
        ctx.fillStyle = '#00B2D2';
        ctx.fillRect(0, backgroundLayer2.y, 960, 540);
        ctx.fillRect(0, backgroundLayer2.y - 540, 960, 540);
        // Draw player
        ctx.fillStyle = '#C0C0C0';
        ctx.fillRect(player.x, player.y, player.width, player.height);
        // Draw enemies
        for (let e of enemies) {
            ctx.fillStyle = '#FF5000';
            ctx.fillRect(e.x, e.y, e.width, e.height);
        }
        // Draw HUD
        GF.Draw.text(ctx, 'SCORE: ' + score, 480, 30, {size:24, color:'#FFFFFF'});
        if (player.health < 3) {
            ctx.fillStyle = 'rgba(255,0,0,0.5)';
            ctx.fillRect(10, 10, player.health * 10, 20);
        }
        // Draw health bar
        ctx.fillStyle = '#00B2D2';
        ctx.fillRect(10, 10, 30, 20);
        ctx.fillStyle = 'rgba(255,0,0,0.5)';
        ctx.fillRect(10 + 30, 10, (player.health - 1) * 10, 20);
        // Draw visual indicators
        ctx.fillStyle = '#FFAA00';
        ctx.fillRect(450, 50, 60, 10);
        ctx.fillStyle = '#C0C0C0';
        ctx.fillText('Objective: Dismantle Enemies', 520, 60);
    }
});

game.titleScreen({subtitle:'Press any key to start', onStart() { game.go('play'); }});
